function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 3 || nums.length > 100000) return 'nums needs 3 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000000)) return 'Each value is an integer from 1 to 10^6.';
  if (!Number.isInteger(k) || k < 1 || k > Math.floor(nums.length / 2)) return 'k is between 1 and n / 2.';
  return null;
}

