function goodIndices(nums, k) {
  const n = nums.length;
  const before = new Array(n).fill(1);
  const after = new Array(n).fill(1);

  for (let i = 1; i < n; i++) {
    if (nums[i] <= nums[i - 1]) {
      before[i] = before[i - 1] + 1;
    }
  }
  for (let i = n - 2; i >= 0; i--) {
    if (nums[i] <= nums[i + 1]) {
      after[i] = after[i + 1] + 1;
    }
  }

  const result = [];
  for (let i = k; i < n - k; i++) {
    if (before[i - 1] >= k && after[i + 1] >= k) {
      result.push(i);
    }
  }
  return result;
}

