function goodIndices(nums, k) {
  const out = [];
  for (let i = k; i < nums.length - k; i++) {
    let ok = true;
    for (let j = i - k + 1; j < i; j++) if (nums[j] > nums[j - 1]) ok = false;
    for (let j = i + 2; j <= i + k; j++) if (nums[j] < nums[j - 1]) ok = false;
    if (ok) out.push(i);
  }
  return out;
}

