function generate(rand, size) {
  if (size === 'small') {
    const n = 3 + Math.floor(rand() * 9);
    const top = 1 + Math.floor(rand() * 5);
    const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
    const k = 1 + Math.floor(rand() * Math.floor(n / 2));
    return [nums, k];
  }
  // Large: a random walk made of flat, rising and falling stretches, so long monotone runs (and good indices) appear.
  const n = 2000;
  const nums = [];
  let value = 1 + Math.floor(rand() * 1000000);
  while (nums.length < n) {
    const length = 1 + Math.floor(rand() * 80);
    const direction = Math.floor(rand() * 3) - 1;
    for (let j = 0; j < length && nums.length < n; j++) {
      value += direction * Math.floor(rand() * 4);
      value = Math.min(1000000, Math.max(1, value));
      nums.push(value);
    }
  }
  const k = rand() < 0.2 ? 1 + Math.floor(rand() * 1000) : 1 + Math.floor(rand() * 40);
  return [nums, k];
}
